import json, os, time
from collections import Counter
from datetime import datetime, timezone, timedelta

path = r'"'E:\\\\codex-LOOP\\\\codex-loop-s-f2\\\\data\\\\lifecycle\\\\exec_roster.json'
FRESH_S = 30.0
TZ = timezone(timedelta(hours=8))
decoder = json.JSONDecoder()

def iso(ts):
    if not isinstance(ts, (int, float)):
        return None
    return datetime.fromtimestamp(float(ts), TZ).isoformat(timespec='microseconds')

class S:
    def __init__(self, path):
        self.fh = open(path, 'r', encoding='utf-8')
        self.buf = ''
        self.i = 0
    def fill(self, need=1):
        while (len(self.buf) - self.i) < need:
            chunk = self.fh.read(256*1024)
            if not chunk:
                return False
            if self.i > 512*1024:
                self.buf = self.buf[self.i:]; self.i=0
            self.buf += chunk
        return True
    def skip(self):
        while True:
            self.fill(1)
            if self.i >= len(self.buf):
                return False
            if self.buf[self.i] in ' \\n\\r\\t,':
                self.i += 1; continue
            return True
    def dec(self):
        while True:
            self.fill(64)
            try:
                val,j = decoder.raw_decode(self.buf, self.i)
                self.i=j; return val
            except json.JSONDecodeError:
                if not self.fill(len(self.buf)-self.i+65536):
                    raise

st=os.stat(path)
now=time.time()
s=S(path); s.fill(64); s.skip(); assert s.buf[s.i]=='{'; s.i+=1
missing_hb=[]
stale_ages=[]
fresh_hb_only=0
stale_hb_only=0
running_no_hb=0
lost_jobs=[]
state_role=Counter()
now_iso=iso(now)
while True:
    s.skip()
    if s.buf[s.i]=='}':
        break
    key=s.dec(); s.skip();
    if s.buf[s.i]==':': s.i+=1
    s.skip()
    if key=='jobs':
        assert s.buf[s.i]=='{'; s.i+=1
        while True:
            s.skip()
            if s.buf[s.i]=='}':
                s.i+=1; break
            jid=s.dec(); s.skip()
            if s.buf[s.i]==':': s.i+=1
            s.skip()
            job=s.dec()
            if not isinstance(job, dict):
                continue
            state=str(job.get('state') or 'unknown')
            role=str(job.get('role') or '')
            state_role[(state, role)] += 1
            hb=job.get('heartbeat_at'); ua=job.get('updated_at')
            hb_f=float(hb) if isinstance(hb,(int,float)) else 0.0
            ua_f=float(ua) if isinstance(ua,(int,float)) else 0.0
            if not isinstance(hb,(int,float)):
                missing_hb.append({'packet_id': job.get('packet_id') or jid, 'state': state, 'updated_at': ua, 'updated_iso': iso(ua), 'role': role, 'task_name': job.get('task_name'), 'failure': job.get('failure')})
            if state=='lost':
                lost_jobs.append({'packet_id': job.get('packet_id') or jid, 'task_name': job.get('task_name'), 'updated_at': ua, 'updated_iso': iso(ua), 'heartbeat_at': hb, 'heartbeat_iso': iso(hb)})
            if state=='running':
                used=max(hb_f, ua_f)
                age = None if used<=0 else now-used
                if age is None or age>FRESH_S:
                    stale_ages.append(age)
                hb_age = None if hb_f<=0 else now-hb_f
                if hb_age is None or hb_age>FRESH_S:
                    stale_hb_only += 1
                    if hb_f<=0:
                        running_no_hb += 1
                else:
                    fresh_hb_only += 1
    else:
        s.dec()
s.fh.close()
buckets=Counter()
for age in stale_ages:
    if age is None:
        buckets['none'] += 1
    elif age < 60:
        buckets['30-60s'] += 1
    elif age < 300:
        buckets['1-5min'] += 1
    elif age < 3600:
        buckets['5-60min'] += 1
    elif age < 86400:
        buckets['1-24h'] += 1
    elif age < 7*86400:
        buckets['1-7d'] += 1
    else:
        buckets['>7d'] += 1
print(json.dumps({
  'now': now,
  'now_iso': now_iso,
  'size': st.st_size,
  'mtime_iso': iso(st.st_mtime),
  'missing_hb': missing_hb,
  'lost_jobs': lost_jobs,
  'fresh_hb_only': fresh_hb_only,
  'stale_hb_only': stale_hb_only,
  'running_no_hb': running_no_hb,
  'stale_age_buckets': dict(buckets),
  'stale_age_minmax': [None if not stale_ages else min(a for a in stale_ages if a is not None), None if not stale_ages else max(a for a in stale_ages if a is not None)],
  'state_role': {f'{k[0]}|{k[1]}': v for k,v in state_role.items()},
}, ensure_ascii=False, indent=2, default=str))
